VQ(a){var s=null
return A.aG(a,s,this.a,s,"\u0634\u064a\u0643 \u0648\u0627\u062d\u062f \u062a\u0645\u062a \u062a\u0633\u0648\u064a\u062a\u0647",""+a+" \u0634\u064a\u0643\u0627\u062a \u062a\u0645\u062a \u062a\u0633\u0648\u064a\u062a\u0647\u0627",s,s)+" \u2014 \u0645\u0639\u0638\u0645\u0647\u0627 \u0645\u0633\u062a\u0648\u0631\u062f\u0629 \u0645\u0646 Manager.io \u2014 \u063a\u064a\u0631 \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0642\u064a\u0648\u062f \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062a\u064a \u062a\u0645\u062b\u0644\u0647\u0627. \u062d\u0630\u0641 \u0623\u062d\u062f\u0647\u0627 \u0627\u0644\u0622\u0646 \u0633\u064a\u0632\u064a\u0644 \u0641\u0642\u0637 \u0627\u0644\u0634\u064a\u0643 \u0627\u0644\u0645\u0631\u0626\u064a\u060c \u062a\u0627\u0631\u0643\u064b\u0627 \u0623\u0645\u0648\u0627\u0644\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 (\u0627\u0644\u0630\u0645\u0645 \u0627\u0644\u062f\u0627\u0626\u0646\u0629\u060c \u0627\u0644\u0630\u0645\u0645 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0627\u0644\u0646\u0642\u062f\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u0643) \u062f\u0648\u0646 \u0645\u0633\u0627\u0633 \u062a\u0645\u0627\u0645\u064b\u0627. \u064a\u0631\u0628\u0637 \u0643\u0644 \u0648\u0627\u062d\u062f \u0628\u0642\u064a\u0648\u062f\u0647 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u062d\u062a\u0649 \u064a\u0639\u0645\u0644 \u0627\u0644\u062d\u0630\u0641 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d \u0645\u0646 \u0627\u0644\u0622\u0646 \u0641\u0635\u0627\u0639\u062f\u064b\u0627 \u2014 \u0644\u0627 \u064a\u062d\u0631\u0643 \u0623\u064a \u0623\u0645\u0648\u0627\u0644 \u0628\u062d\u062f \u0630\u0627\u062a\u0647."},
