gVv(){return"\u0939\u0930 \u0917\u094d\u0930\u093e\u0939\u0915, \u0906\u092a\u0942\u0930\u094d\u0924\u093f\u0915\u0930\u094d\u0924\u093e, \u0906\u0907\u091f\u092e, \u0914\u0930 \u0932\u0947\u0928\u0926\u0947\u0928 \u2014 \u090f\u0915 \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u0928\u0908 \u0915\u0902\u092a\u0928\u0940 \u092e\u0947\u0902 \u0935\u093e\u092a\u0938 \u092e\u093f\u091f\u093e \u0926\u093f\u092f\u093e \u0917\u092f\u093e\u0964 \u0915\u0947\u0935\u0932 \u0936\u093e\u0916\u093e(\u090f\u0902), \u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932, \u0914\u0930 \u0938\u094d\u091f\u093e\u092b \u0932\u0949\u0917\u093f\u0928 \u092c\u091a\u0924\u0947 \u0939\u0948\u0902\u0964 \u0907\u0938\u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0926\u094b\u092c\u093e\u0930\u093e \u091a\u0932\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0921\u0941\u092a\u094d\u0932\u093f\u0915\u0947\u091f \u092f\u093e \u092c\u093f\u0917\u0921\u093c\u0947 \u0939\u0941\u090f \u0906\u092f\u093e\u0924 \u0915\u094b \u0938\u093e\u092b \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0930\u0947\u0902\u0964"},
gCy(){return"\u0930\u0940\u0938\u0947\u091f"},
gVA(){return"\u0938\u092d\u0940 \u0907\u0928\u094d\u0935\u0947\u0902\u091f\u0930\u0940 \u0930\u0940\u0938\u0947\u091f \u0915\u0930\u0947\u0902"},
gVz(){return"\u0939\u0930 \u0906\u0907\u091f\u092e \u0915\u0947 \u0938\u094d\u091f\u0949\u0915, \u092e\u0942\u0935\u092e\u0947\u0902\u091f \u0907\u0924\u093f\u0939\u093e\u0938, \u0914\u0930 \u0932\u093e\u0917\u0924 \u092a\u0930\u0924\u094b\u0902 \u0915\u094b \u0936\u0942\u0928\u094d\u092f \u092a\u0930 \u0935\u093e\u092a\u0938 \u092e\u093f\u091f\u093e\u090f\u0902\u0964"},
gVE(){return"\u0938\u092d\u0940 \u0932\u0947\u0928\u0926\u0947\u0928 \u0930\u0940\u0938\u0947\u091f \u0915\u0930\u0947\u0902"},
gVD(){return"\u0939\u0930 \u091a\u093e\u0932\u093e\u0928, \u0916\u0930\u0940\u0926, \u0928\u094b\u091f, \u091a\u0947\u0915, \u0921\u093f\u0932\u0940\u0935\u0930\u0940, \u0935\u093e\u0909\u091a\u0930, \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f, \u0938\u094d\u091f\u0949\u0915 \u092e\u0942\u0935\u092e\u0947\u0902\u091f, \u092a\u0947\u0930\u094b\u0932 \u0930\u0928, \u0914\u0930 \u0911\u0921\u093f\u091f \u0932\u0949\u0917 \u2014 \u090f\u0915 \u0939\u0940 \u092c\u093e\u0930 \u092e\u0947\u0902 \u092e\u093f\u091f\u093e \u0926\u093f\u092f\u093e \u0917\u092f\u093e\u0964 \u0915\u0902\u092a\u0928\u0940 \u0938\u0947\u091f\u0905\u092a (\u0917\u094d\u0930\u093e\u0939\u0915, \u0906\u092a\u0942\u0930\u094d\u0924\u093f\u0915\u0930\u094d\u0924\u093e, \u0906\u0907\u091f\u092e, \u0938\u094d\u091f\u093e\u092b, \u0916\u093e\u0924\u094b\u0902 \u0915\u093e \u091a\u093e\u0930\u094d\u091f) \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u0935\u0948\u0938\u0947 \u0939\u0940 \u0930\u0939\u0924\u093e \u0939\u0948\u0964"},
gQD(){return"\u0915\u0947\u0935\u0932 \u0938\u094d\u0935\u093e\u092e\u0940 \u0939\u0940 \u0915\u0902\u092a\u0928\u0940 \u0915\u0947 \u0921\u0947\u091f\u093e \u0915\u093e \u092c\u0948\u0915\u0905\u092a \u092f\u093e \u092a\u0941\u0928\u0930\u094d\u0938\u094d\u0925\u093e\u092a\u0928\u093e \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948\u0964"},
